Lemma rg14_H2 : forall regs m (i nfw d4 pdf psrow pdrow : Z),
  (0 <= i < 2 ^ 24)%Z -> (1 <= nfw < 2 ^ 26)%Z -> (0 <= d4 < 2 ^ 26)%Z ->
  getr regs 28 = Z_to_bv 64 nfw -> getr regs 14 = Z_to_bv 64 d4 -> getr regs 11 = Z_to_bv 64 i -> getr regs 18 = Z_to_bv 64 (4 * nfw) ->
  getr regs 29 = Z_to_bv 64 pdf -> getr regs 9 = Z_to_bv 64 psrow -> getr regs 19 = Z_to_bv 64 pdrow ->
  exists regs',
    msteps SEGS (mkst regs (0x7c2f0 : word) m rom) (mkst regs' (0x7c308 : word) m rom)
    /\ getr regs' 7 = Z_to_bv 64 (pdf + 4 * nfw + d4 * i) /\ getr regs' 20 = Z_to_bv 64 psrow /\ getr regs' 21 = Z_to_bv 64 pdrow
    /\ regs_agree (fun r => In r [7; 20; 21]%list) regs regs'.
Proof.
