Lemma rg14_T2 : forall (last : bool) regs m (i dh d4 s4 psrow pdrow : Z),
  (0 <= i)%Z -> (i + 1 <= dh)%Z -> (dh < 2 ^ 31)%Z -> (if last then i + 1 = dh else i + 1 < dh)%Z ->
  getr regs 8 = Z_to_bv 64 i -> getr regs 11 = Z_to_bv 64 i -> getr regs 12 = Z_to_bv 64 dh ->
  getr regs 14 = Z_to_bv 64 d4 -> getr regs 13 = Z_to_bv 64 s4 -> getr regs 9 = Z_to_bv 64 psrow -> getr regs 19 = Z_to_bv 64 pdrow ->
  exists regs',
    msteps SEGS (mkst regs (0x7c2dc : word) m rom) (mkst regs' (if last then (0x7b4c4 : word) else (0x7c2f0 : word)) m rom)
    /\ getr regs' 8 = Z_to_bv 64 (i + 1) /\ getr regs' 11 = Z_to_bv 64 (i + 1)
    /\ getr regs' 9 = Z_to_bv 64 (psrow + s4) /\ getr regs' 19 = Z_to_bv 64 (pdrow + d4)
