(* [comment removed for export] *)
Lemma rg14_X1 : forall (nofull : bool) regs m (psfull pdfull nfw swpl dwpl : Z),
  (0 <= swpl < 2 ^ 24)%Z -> (0 <= dwpl < 2 ^ 24)%Z -> (0 <= nfw < 2 ^ 26)%Z ->
  getr regs 19 = Z_to_bv 64 (if nofull then 1 else 0) -> (nofull = false -> getr regs 9 = Z_to_bv 64 psfull /\ getr regs 29 = Z_to_bv 64 pdfull) ->
  getr regs 28 = Z_to_bv 64 nfw -> getr regs 13 = Z_to_bv 64 (4 * swpl) -> getr regs 14 = Z_to_bv 64 (4 * dwpl) ->
  exists regs',
    msteps SEGS (mkst regs (0x7b4c0 : word) m rom) (mkst regs' (if nofull then (0x7b4c4 : word) else (0x7c2f0 : word)) m rom)
    /\ (nofull = false -> getr regs' 11 = Z_to_bv 64 0 /\ getr regs' 8 = Z_to_bv 64 0 /\ getr regs' 14 = Z_to_bv 64 (4 * dwpl)
                          /\ getr regs' 9 = Z_to_bv 64 (psfull + 4) /\ getr regs' 13 = Z_to_bv 64 (4 * swpl) /\ getr regs' 18 = Z_to_bv 64 (4 * nfw)
                          /\ getr regs' 19 = Z_to_bv 64 pdfull)
    /\ regs_agree (fun r => In r [8; 9; 11; 18; 19]%list) regs regs'.
